<?php
declare(strict_types=1);
function mcp_tools(): array {
    $object=fn($properties,$required=[])=>['type'=>'object','properties'=>$properties,'required'=>$required,'additionalProperties'=>false];$string=['type'=>'string'];
    $read=['readOnlyHint'=>true,'destructiveHint'=>false,'openWorldHint'=>false];$write=['readOnlyHint'=>false,'destructiveHint'=>false,'idempotentHint'=>true,'openWorldHint'=>false];
    $schemaRead=[['type'=>'oauth2','scopes'=>['cubo:read']]];$schemaWrite=[['type'=>'oauth2','scopes'=>['cubo:write']]];
    return [
        ['name'=>'search_clients','description'=>'Buscar fichas, contactos y alias. No sumar histórico a ingresos.','inputSchema'=>$object(['query'=>$string]),'annotations'=>$read,'securitySchemes'=>$schemaRead],
        ['name'=>'get_client','description'=>'Consultar una ficha con servicios, pendientes e histórico original sin inventar fechas o monedas.','inputSchema'=>$object(['clientId'=>$string],['clientId']),'annotations'=>$read,'securitySchemes'=>$schemaRead],
        ['name'=>'list_pending','description'=>'Consultar cobros por cliente, periodo o pagador; saldos históricos separados.','inputSchema'=>$object(['clientId'=>$string,'payerId'=>$string,'period'=>$string]),'annotations'=>$read,'securitySchemes'=>$schemaRead],
        ['name'=>'prepare_operation','description'=>'Preparar operación sin escribir finanzas. client_upsert: id opcional, name/status/contact/notes/aliases. project_upsert: clientId/name/kind/amount/currency/start y acuerdo mensual explícito; no inventar fechas. payment: chargeId/amount/receiptDate (null si desconocida)/mxn (solo conversión confirmada)/note. group_payment: payerId/group (SEO o Ads)/period (YYYY-MM)/amount/receiptDate/note. Solo importes confirmados. Devuelve enlace privado que el propietario debe aprobar; luego usar commit_operation.','inputSchema'=>$object(['action'=>['type'=>'string','enum'=>['client_upsert','project_upsert','payment','group_payment']],'data'=>['type'=>'object','additionalProperties'=>true]],['action','data']),'annotations'=>array_replace($write,['idempotentHint'=>false]),'securitySchemes'=>$schemaWrite],
        ['name'=>'commit_operation','description'=>'Guardar únicamente una propuesta aprobada por el propietario. Reintentos del mismo proposalId no duplican movimientos; un conflicto requiere una propuesta nueva.','inputSchema'=>$object(['proposalId'=>$string],['proposalId']),'annotations'=>$write,'securitySchemes'=>$schemaWrite]
    ];
}
function mcp_call(string $name,array $args,array $user): array {
    $write=in_array($name,['prepare_operation','commit_operation'],true);mcp_scope($user,$write?'cubo:write':'cubo:read');
    if($name==='commit_operation'){
        operation_keys($args,['proposalId']);$id=$args['proposalId']??'';$p=mcp_store(fn(&$s)=>$s['proposals'][$id]??null);ensure($p&&$p['userId']===$user['id']&&$p['clientId']===$user['oauthClient']&&($p['resource']??null)===mcp_resource()&&($p['approved']??false)&&$p['expires']>=time(),'Propuesta no aprobada o vencida.');
        return save_state(['state'=>$p['state'],'revision'=>$p['revision'],'requestId'=>$id,'action'=>'MCP: '.$p['action']],$user);
    }
    $current=mcp_read_state();$s=$current['state'];
    if($name==='search_clients'){operation_keys($args,['query']);$query=strtolower(trim((string)($args['query']??'')));$out=[];foreach($s['clients'] as $c)if($query===''||str_contains(strtolower($c['name'].' '.($c['contact']??'').' '.implode(' ',$c['aliases']??[])),$query))$out[]=['id'=>$c['id'],'name'=>$c['name'],'status'=>$c['status'],'contact'=>$c['contact']??'','aliases'=>$c['aliases']??[]];return ['clients'=>array_slice($out,0,100),'revision'=>$current['revision']];}
    if($name==='get_client'){operation_keys($args,['clientId']);$client=null;foreach($s['clients'] as $c)if($c['id']===($args['clientId']??null))$client=$c;ensure($client!==null,'Ficha no encontrada.');$services=array_values(array_filter($s['services'],fn($v)=>$v['clientId']===$client['id']));$charges=array_values(array_filter($s['charges'],fn($v)=>$v['clientId']===$client['id']));$ids=array_column($charges,'id');$payerCharges=array_values(array_filter($s['charges'],fn($v)=>($v['payerId']??null)===$client['id']));$payerIds=array_column($payerCharges,'id');return ['payerCharges'=>$payerCharges,'payerPayments'=>array_values(array_filter($s['payments'],fn($v)=>in_array($v['chargeId'],$payerIds,true))),'client'=>$client,'services'=>$services,'charges'=>$charges,'payments'=>array_values(array_filter($s['payments'],fn($v)=>in_array($v['chargeId'],$ids,true))),'historyMeaning'=>'Las notas y saldos iniciales sin fecha no son ingresos de un mes. payerCharges/payerPayments son aplicaciones de los proyectos, no cargos adicionales del pagador. groupReceiptId identifica un mismo pago distribuido; no sumar otra vez el importe agrupado.','revision'=>$current['revision']];}
    if($name==='list_pending'){operation_keys($args,['clientId','payerId','period']);$out=[];foreach($s['charges'] as $c)if(!($c['cancelled']??false)&&operation_charge_balance($s,$c)>0&&(!isset($args['clientId'])||$args['clientId']===$c['clientId'])&&(!isset($args['payerId'])||$args['payerId']===($c['payerId']??null))&&(!isset($args['period'])||$args['period']===$c['period']))$out[]=$c+['balance'=>operation_charge_balance($s,$c)];$opening=[];foreach($s['clients'] as $c)if(isset($c['opening'])&&(!isset($args['clientId'])||$args['clientId']===$c['id'])&&!isset($args['period'])&&!isset($args['payerId']))$opening[]=['clientId'=>$c['id'],'opening'=>$c['opening']];return ['charges'=>$out,'historicalOpening'=>$opening,'revision'=>$current['revision']];}
    if($name==='prepare_operation'){mcp_rate_limit('proposal-'.$user['id'],20);operation_keys($args,['action','data']);ensure(is_string($args['action']??null)&&is_array($args['data']??null),'Operación incompleta.');$s['settings']['today']=date('Y-m-d');$new=apply_operation($s,$args['action'],$args['data']);$id=operation_id();$p=['userId'=>$user['id'],'clientId'=>$user['oauthClient'],'resource'=>mcp_resource(),'revision'=>$current['revision'],'action'=>$args['action'],'data'=>$args['data'],'state'=>$new,'approved'=>false,'expires'=>time()+3600];mcp_store(function(&$store)use($id,$p){$store['proposals'][$id]=$p;});return ['proposalId'=>$id,'approvalUrl'=>config()['app_origin'].'/mcp-approve.php?id='.rawurlencode($id),'requiresOwnerApproval'=>true,'revision'=>$current['revision'],'operation'=>$args['action']];}
    throw new DomainException('Herramienta no disponible.');
}
